        flushOnBlur = false,
        diffMarkdown,
        hideToolbar = false,
        overlayContainer,
        placeholders = EMPTY_PLACEHOLDERS,
        readOnly = false,
        stickyToolbar = false,
        toolbarContents: customToolbarContents,
        viewMode,
